INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v1_portugues','Simulado de Português — ENEM','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','portugues','["Interpretação de texto","Coesão textual","Variação linguística","Argumentação","Funções da linguagem"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_portugues_q1','nivora_enem_v1_portugues','Em uma campanha fictícia de biblioteca, lê-se: “Leve um livro. Devolva uma ideia.” A segunda frase, associada à primeira, sugere que a leitura deve favorecer:','A campanha associa o empréstimo à elaboração de ideias. “Devolver uma ideia” tem sentido figurado: compartilhar reflexões, e não substituir materialmente o livro. Não há referência a taxa, censura ou abandono da leitura.','Interpretação de texto',0,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q1_o0','nivora_enem_v1_portugues_q1','A devolução de um objeto diferente do emprestado.',0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q1_o1','nivora_enem_v1_portugues_q1','A substituição dos livros por opiniões sem leitura.',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q1_o2','nivora_enem_v1_portugues_q1','A produção e a circulação de reflexões entre leitores.',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q1_o3','nivora_enem_v1_portugues_q1','A cobrança de uma taxa por cada empréstimo.',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q1_o4','nivora_enem_v1_portugues_q1','A proibição de discordar dos autores.',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_portugues_q2','nivora_enem_v1_portugues','Leia o trecho autoral: “A cidade ampliou as ciclovias. Entretanto, faltam conexões entre os bairros.” A palavra “entretanto” estabelece entre as frases uma relação de:','“Entretanto” introduz oposição ou ressalva. A ampliação é um avanço, mas a ausência de conexões limita seu alcance. A relação não é temporal, condicional, causal ou conclusiva.','Coesão textual',1,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q2_o0','nivora_enem_v1_portugues_q2','Causa, pois as ciclovias provocaram a falta de conexão.',0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q2_o1','nivora_enem_v1_portugues_q2','Conclusão, pois a segunda frase resume a primeira.',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q2_o2','nivora_enem_v1_portugues_q2','Tempo, pois indica quando ocorreu a ampliação.',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q2_o3','nivora_enem_v1_portugues_q2','Contraste, pois apresenta uma limitação do avanço mencionado.',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q2_o4','nivora_enem_v1_portugues_q2','Condição, pois a ampliação depende de uma hipótese.',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_portugues_q3','nivora_enem_v1_portugues','Em entrevista para um documentário sobre sua comunidade, uma moradora usa expressões regionais. A equipe decide preservar essas expressões, sem apresentá-las como erros. Essa decisão reconhece que:','Variações regionais fazem parte da diversidade linguística e podem marcar pertencimento. Reconhecer sua legitimidade não elimina a adequação ao contexto nem torna todas as situações comunicativas iguais.','Variação linguística',2,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_portugues_q3_o0','nivora_enem_v1_portugues_q3','As variedades regionais expressam identidades e são formas legítimas de uso da língua.',0) ON CONFLICT(id) DO NOTHING;
