INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_portugues_q4','nivora_enem_v1_portugues','Um texto autoral defende ampliar o horário de uma biblioteca. Para sustentar a proposta, informa que, em uma consulta com 200 usuários, 140 disseram só poder frequentá-la à noite. O recurso argumentativo utilizado é:','O dado 140 de 200 usuários sustenta a demanda por atendimento noturno. É evidência quantitativa daquela consulta, não prova de que toda a população tenha o mesmo horário disponível.','Argumentação',3,4) ON CONFLICT(id) DO NOTHING;
