INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_portugues_q5','nivora_enem_v1_portugues','Em um cartaz fictício de coleta seletiva está escrito: “Separe o papel limpo e seco. Entregue no ponto de coleta do bairro.” Considerando o objetivo do cartaz, predomina a função:','Os verbos no imperativo orientam o leitor a realizar ações. Por isso predomina a função conativa ou apelativa, embora o texto também transmita informação.','Funções da linguagem',4,1) ON CONFLICT(id) DO NOTHING;
