INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v1_matematica','Simulado de Matemática — ENEM','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','matematica','["Porcentagem","Escala","Estatística","Probabilidade","Função afim"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_matematica_q1','nivora_enem_v1_matematica','Um curso custa R$ 250,00. Uma campanha oferece desconto de 20% e, sobre o preço já reduzido, mais 10% para pagamento à vista. Qual é o preço final?','Após o primeiro desconto: 250 × 0,80 = 200. O segundo é aplicado a 200: 200 × 0,90 = 180. Os percentuais sucessivos não se somam diretamente; o desconto total é de 28%.','Porcentagem',0,2) ON CONFLICT(id) DO NOTHING;
