INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_matematica_q2','nivora_enem_v1_matematica','Em um mapa de escala 1:50 000, um trecho reto de estrada mede 6 cm. Qual é o comprimento real desse trecho?','Cada centímetro representa 50 000 cm. Logo, 6 × 50 000 = 300 000 cm = 3 000 m = 3 km. É necessário converter centímetros em quilômetros.','Escala',1,1) ON CONFLICT(id) DO NOTHING;
