INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_matematica_q3','nivora_enem_v1_matematica','Uma equipe registrou as seguintes durações, em minutos, de sete viagens: 12, 15, 15, 18, 20, 25 e 70. Para representar o valor central sem a forte influência da viagem de 70 minutos, usa a mediana. Qual é essa mediana?','Os sete valores já estão em ordem. A mediana é o quarto valor, 18. A média seria 175/7 = 25, mais afetada pelo valor extremo de 70.','Estatística',2,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_matematica_q3_o0','nivora_enem_v1_matematica_q3','15 minutos',0) ON CONFLICT(id) DO NOTHING;
