INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_matematica_q4','nivora_enem_v1_matematica','Uma caixa contém 3 fichas azuis e 2 vermelhas, indistinguíveis pelo tato. Duas fichas são retiradas ao acaso, sem reposição. Qual é a probabilidade de ambas serem azuis?','A chance de azul na primeira retirada é 3/5. Restam 2 azuis entre 4 fichas: 2/4. O produto é (3/5) × (2/4) = 3/10. Sem reposição, as probabilidades mudam.','Probabilidade',3,0) ON CONFLICT(id) DO NOTHING;
