INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_matematica_q5','nivora_enem_v1_matematica','Uma empresa cobra R$ 12,00 de taxa fixa mais R$ 3,00 por quilômetro percorrido. Uma entrega custou R$ 57,00, sem outras cobranças. Qual foi a distância percorrida?','O modelo é C = 12 + 3d. Para C = 57: 3d = 57 − 12 = 45, portanto d = 15 km. Dividir 57 por 3 ignoraria a taxa fixa.','Função afim',4,4) ON CONFLICT(id) DO NOTHING;
