INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v1_biologia','Simulado de Biologia — ENEM','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','biologia','["Ecologia","Evolução","Genética","Fluxo de energia","Ciclo do carbono"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_biologia_q1','nivora_enem_v1_biologia','Um lago recebe excesso de nutrientes de esgoto. Após intensa proliferação de algas, parte delas morre e é decomposta. A morte de peixes pode ocorrer porque a decomposição aeróbia:','O enriquecimento por nutrientes favorece a eutrofização. A decomposição aeróbia da matéria orgânica consome oxigênio dissolvido, podendo causar hipóxia e morte de peixes. Decompor não equivale a realizar fotossíntese.','Ecologia',0,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q1_o0','nivora_enem_v1_biologia_q1','Produz oxigênio em quantidade ilimitada.',0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q1_o1','nivora_enem_v1_biologia_q1','Consome oxigênio dissolvido necessário aos peixes.',1) ON CONFLICT(id) DO NOTHING;
