INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q1_o4','nivora_enem_v1_biologia_q1','Elimina a respiração dos microrganismos.',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_biologia_q2','nivora_enem_v1_biologia','Em uma população bacteriana, algumas bactérias já possuem uma variante hereditária de resistência. Após exposição a um antibiótico, aumenta a proporção de resistentes. A explicação evolutiva é:','A seleção natural favorece variantes hereditárias que já conferem vantagem naquele ambiente. O antibiótico atua como pressão seletiva; o processo não pressupõe aprendizagem ou mutações dirigidas pela necessidade.','Evolução',1,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q2_o0','nivora_enem_v1_biologia_q2','O antibiótico ensinou cada bactéria a resistir.',0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q2_o1','nivora_enem_v1_biologia_q2','Todas as bactérias sofreram a mesma mutação dirigida.',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q2_o2','nivora_enem_v1_biologia_q2','As bactérias sensíveis escolheram mudar seus genes.',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q2_o3','nivora_enem_v1_biologia_q2','As resistentes tiveram maior sobrevivência e reprodução nesse ambiente.',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q2_o4','nivora_enem_v1_biologia_q2','A resistência surgiu porque a população precisava dela.',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_biologia_q3','nivora_enem_v1_biologia','Em um modelo mendeliano de dominância completa, A é dominante e a é recessivo. Dois indivíduos heterozigotos Aa têm descendentes. Qual a probabilidade de um descendente apresentar o fenótipo recessivo?','Aa × Aa produz AA, Aa, Aa e aa com probabilidades 1/4, 1/4, 1/4 e 1/4. Apenas aa expressa o fenótipo recessivo, portanto 25%, sob as condições do modelo.','Genética',2,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q3_o0','nivora_enem_v1_biologia_q3','25%',0) ON CONFLICT(id) DO NOTHING;
