INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q3_o2','nivora_enem_v1_biologia_q3','75%',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q3_o3','nivora_enem_v1_biologia_q3','100%',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q3_o4','nivora_enem_v1_biologia_q3','0%',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_biologia_q4','nivora_enem_v1_biologia','Em uma cadeia alimentar, a energia disponível nos produtores é estimada em 10 000 kJ. Supondo transferência de 10% a cada nível trófico, quanta energia chega aos consumidores secundários?','Há duas transferências: produtores → consumidores primários → secundários. Assim, 10 000 × 0,10 × 0,10 = 100 kJ. A eficiência de 10% é uma hipótese do problema, não uma constante universal.','Fluxo de energia',3,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q4_o0','nivora_enem_v1_biologia_q4','10 kJ',0) ON CONFLICT(id) DO NOTHING;
