INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_biologia_q5','nivora_enem_v1_biologia','Uma área florestada é desmatada e sua biomassa é queimada. Considerando o carbono que estava armazenado nos tecidos vegetais, qual é uma consequência direta da combustão completa dessa matéria orgânica?','Na combustão completa, o carbono da matéria orgânica é oxidado a CO₂. A perda de vegetação também pode reduzir a fixação futura por fotossíntese, mas a consequência direta solicitada é a emissão pela queima.','Ciclo do carbono',4,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_biologia_q5_o0','nivora_enem_v1_biologia_q5','Conversão de todo o carbono em oxigênio molecular.',0) ON CONFLICT(id) DO NOTHING;
