INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v1_fisica','Simulado de Física — ENEM','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','fisica','["Energia elétrica","Cinemática","Calorimetria","Circuitos elétricos","Ondulatória"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_fisica_q1','nivora_enem_v1_fisica','Um chuveiro de 5 500 W é usado por 20 minutos diários durante 30 dias. Considerando potência constante, qual é o consumo nesse período?','A potência é 5,5 kW. O tempo total é (20/60) × 30 = 10 h. Energia = potência × tempo = 5,5 × 10 = 55 kWh.','Energia elétrica',0,3) ON CONFLICT(id) DO NOTHING;
