INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_fisica_q2','nivora_enem_v1_fisica','Um ônibus percorre 120 km em 2 horas e depois fica parado por 30 minutos. Qual é a velocidade escalar média considerando todo esse intervalo, inclusive a parada?','A distância total é 120 km e o tempo total é 2,5 h. A velocidade escalar média é 120/2,5 = 48 km/h. Usar apenas as duas horas de movimento exclui a parada indevidamente.','Cinemática',1,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_fisica_q2_o0','nivora_enem_v1_fisica_q2','48 km/h',0) ON CONFLICT(id) DO NOTHING;
