INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_fisica_q3','nivora_enem_v1_fisica','Para aquecer 500 g de água de 20 °C a 40 °C, considere calor específico de 4,2 J/(g·°C), sem mudança de fase ou perdas. Qual é a energia necessária?','Q = mcΔT = 500 × 4,2 × (40 − 20) = 42 000 J. A variação de temperatura é 20 °C, não a temperatura final de 40 °C.','Calorimetria',2,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_fisica_q3_o0','nivora_enem_v1_fisica_q3','4 200 J',0) ON CONFLICT(id) DO NOTHING;
