INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_fisica_q4','nivora_enem_v1_fisica','Um resistor ôhmico de 20 Ω é ligado a uma fonte ideal de 10 V. Qual é a corrente elétrica que o atravessa?','Pela lei de Ohm, I = U/R = 10/20 = 0,5 A. A resistência e a tensão foram dadas diretamente, sem outros resistores no circuito.','Circuitos elétricos',3,1) ON CONFLICT(id) DO NOTHING;
