INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_fisica_q5','nivora_enem_v1_fisica','Uma onda periódica propaga-se a 340 m/s com frequência de 170 Hz. Qual é seu comprimento de onda?','A relação v = λf fornece λ = v/f = 340/170 = 2 m. Frequência e comprimento de onda são grandezas distintas.','Ondulatória',4,2) ON CONFLICT(id) DO NOTHING;
