INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_quimica_q1','nivora_enem_v1_quimica','Um laboratório dilui 100 mL de solução de concentração 2,0 mol/L, adicionando água até o volume final de 500 mL. Sem reação ou perda de soluto, a concentração final é:','A quantidade de soluto permanece constante: C₁V₁ = C₂V₂. Portanto, C₂ = (2,0 × 100)/500 = 0,40 mol/L. O volume final é 500 mL, e não 600 mL.','Soluções',0,4) ON CONFLICT(id) DO NOTHING;
