INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_quimica_q2','nivora_enem_v1_quimica','Na combustão completa do metano, CH₄ + 2 O₂ → CO₂ + 2 H₂O. Para queimar 16 g de CH₄, qual massa de O₂ é necessária? Considere massas molares: CH₄ = 16 g/mol e O₂ = 32 g/mol.','16 g de metano correspondem a 1 mol. A equação exige 2 mol de O₂ por mol de metano. A massa necessária é 2 × 32 = 64 g.','Estequiometria',1,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_quimica_q2_o0','nivora_enem_v1_quimica_q2','16 g',0) ON CONFLICT(id) DO NOTHING;
