INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_quimica_q2_o3','nivora_enem_v1_quimica_q2','96 g',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_quimica_q2_o4','nivora_enem_v1_quimica_q2','128 g',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_quimica_q3','nivora_enem_v1_quimica','Em uma solução aquosa diluída idealizada, a concentração de H₃O⁺ é 1,0 × 10⁻³ mol/L. Usando pH = −log₁₀[H₃O⁺], qual é o pH?','log₁₀(10⁻³) = −3. Assim, pH = −(−3) = 3. A solução é ácida; pH não é numericamente igual à concentração.','Acidez',2,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_quimica_q3_o0','nivora_enem_v1_quimica_q3','3',0) ON CONFLICT(id) DO NOTHING;
