INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_quimica_q4','nivora_enem_v1_quimica','Uma amostra contém somente água e areia insolúvel. Para reter a areia e obter a água como filtrado, o procedimento mais direto é:','A filtração separa um sólido insolúvel de um líquido quando os poros retêm o sólido. A pergunta pede a água como filtrado, não uma separação de líquidos miscíveis nem uma transformação química.','Separação de misturas',3,3) ON CONFLICT(id) DO NOTHING;
