INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_quimica_q5','nivora_enem_v1_quimica','Em uma pilha, um eletrodo de zinco sofre a transformação Zn(s) → Zn²⁺(aq) + 2 e⁻. Nesse eletrodo ocorre:','O zinco metálico perde dois elétrons e forma Zn²⁺. Perda de elétrons caracteriza oxidação, que ocorre no ânodo da pilha. Redução é ganho de elétrons.','Eletroquímica',4,1) ON CONFLICT(id) DO NOTHING;
