INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v1_humanas','Simulado de Ciências Humanas — ENEM','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','humanas','["Urbanização","Cartografia","Demografia","Trabalho e industrialização","Patrimônio cultural"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_humanas_q1','nivora_enem_v1_humanas','Após substituir solo permeável por asfalto, um bairro apresenta maior escoamento superficial durante chuvas de mesma intensidade e duração. Qual processo explica diretamente essa mudança?','A impermeabilização reduz a infiltração local e aumenta a parcela de chuva que escoa pela superfície. Isso pode sobrecarregar a drenagem, dependendo de sua capacidade e de outros fatores.','Urbanização',0,2) ON CONFLICT(id) DO NOTHING;
