INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_humanas_q2','nivora_enem_v1_humanas','Em um mapa orientado com o norte para cima, a escola está à direita da praça, sobre a mesma linha horizontal. Em que direção a escola está em relação à praça?','Com norte para cima, leste corresponde à direita e oeste à esquerda. Como os pontos estão na mesma linha horizontal, não há componente norte ou sul para indicar nordeste ou sudeste.','Cartografia',1,4) ON CONFLICT(id) DO NOTHING;
