INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_humanas_q3','nivora_enem_v1_humanas','Uma população apresenta queda duradoura da fecundidade e aumento da sobrevivência nas idades adultas e avançadas. Mantidos esses processos, qual mudança na estrutura etária é esperada?','Menos nascimentos reduzem a renovação pela base, e maior sobrevivência amplia a presença de pessoas em idades elevadas. O resultado esperado é envelhecimento da estrutura etária; isso não implica crescimento populacional infinito.','Demografia',2,0) ON CONFLICT(id) DO NOTHING;
