INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_humanas_q4','nivora_enem_v1_humanas','Em uma fábrica, cada trabalhador executa repetidamente uma etapa específica, enquanto máquinas e supervisores coordenam o ritmo da produção. Em comparação com um artesão que domina a fabricação integral, essa organização se caracteriza pela:','A divisão em etapas fragmenta o trabalho e permite coordenar seu ritmo. O trabalhador deixa de realizar necessariamente o produto inteiro. Isso não elimina hierarquia nem garante autonomia completa.','Trabalho e industrialização',3,1) ON CONFLICT(id) DO NOTHING;
