INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v1_humanas_q4_o4','nivora_enem_v1_humanas_q4','Autonomia completa de cada trabalhador sobre o ritmo coletivo.',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v1_humanas_q5','nivora_enem_v1_humanas','Uma comunidade registra relatos de mestres locais sobre cantos transmitidos oralmente entre gerações. Ao valorizar essa prática, a iniciativa reconhece como patrimônio:','Patrimônio cultural também abrange saberes, práticas e expressões transmitidos socialmente. A oralidade pode preservar memória e identidade; o reconhecimento não depende de preço comercial ou de absoluta imutabilidade.','Patrimônio cultural',4,3) ON CONFLICT(id) DO NOTHING;
